func MakeViewPublic(ac ZAnalytics.Client) {
    permissions := map[string]bool{"export": true}
    config := map[string]interface{}{
        "publicPermLevel": 1,
        "permissions": permissions,
    }
    view := ZAnalytics.GetViewInstance(&ac, orgId, workspaceId, viewId)
